smart.css:
.smc-root {
  color: var(--smc-text, #1e293b);
  font-family: var(--smc-font-body, system-ui, -apple-system, sans-serif);
  font-size: 16.5px;
  line-height: 1.8;
}

.smc-root h2,
.smc-root h3 {
  color: var(--smc-primary, #0f172a);
  font-family: var(--smc-font-heading, inherit);
  font-weight: 700;
  line-height: 1.35;
}

.smc-root h2 {
  font-size: clamp(22px, 3.5vw, 29px);
  margin: 38px 0 16px;
  padding-bottom: 10px;
  border-bottom: 2px solid color-mix(in srgb, var(--smc-primary, #0f172a) 15%, transparent);
}

.smc-root h3 {
  font-size: 18.5px;
  margin: 26px 0 10px;
}

.smc-root p {
  margin: 0 0 16px;
}

.smc-root a {
  color: var(--smc-accent, #c2410c);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.smc-root a:hover {
  color: var(--smc-primary, #0f172a);
}

.smc-root table {
  width: 100%;
  margin: 22px 0 32px;
  border-collapse: collapse;
  border-radius: var(--smc-radius, 8px);
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0,0,0,0.04);
}

.smc-root th,
.smc-root td {
  padding: 14px 16px;
  border: 1px solid var(--smc-border, #e2e8f0);
  text-align: left;
}

.smc-root th {
  background: var(--smc-primary, #0f172a);
  color: #ffffff;
  font-weight: 650;
  font-size: 15px;
}

.smc-root tbody tr:nth-child(even) {
  background: var(--smc-surface, #f8fafc);
}

.smc-root figure {
  margin: 26px 0 32px;
  text-align: center;
}

.smc-root figure img {
  max-width: 100%;
  height: auto;
  border-radius: var(--smc-radius, 8px);
  box-shadow: 0 4px 14px rgba(0,0,0,0.08);
}

.smc-root figure figcaption {
  font-size: 14px;
  color: #64748b;
  margin-top: 10px;
  font-style: italic;
}

.smc-cluster-box {
  margin: 36px 0;
  padding: 24px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-left: 4px solid var(--smc-accent, #c2410c);
  border-radius: var(--smc-radius, 8px);
}

versions.css:
.smc-root {
  container-name: smc;
  container-type: inline-size;
  max-width: 900px;
  margin: 0 auto;
  color: var(--smc-text);
  background: var(--smc-bg);
  font-family: var(--smc-font-body);
  font-size: 16px;
  line-height: 1.75;
}
.smc-root * { box-sizing: border-box; }
.smc-root > h2:first-child {
  margin: 0 0 14px;
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
  font-size: 29px;
  line-height: 1.3;
}
.smc-root > h2:first-child + p {
  margin: 0 0 22px;
  padding: 18px 20px;
  border-left: 4px solid var(--smc-accent);
  border-radius: 0 var(--smc-radius) var(--smc-radius) 0;
  background: color-mix(in srgb, var(--smc-accent) 6%, var(--smc-bg));
}
.smc-root .smc-section {
  margin: 0;
  padding: 24px 4px;
  border-bottom: 1px solid var(--smc-border);
}
.smc-root .smc-heading {
  margin: 0 0 15px;
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
  font-size: 27px;
  line-height: 1.32;
}
.smc-root .smc-copy {
  margin: 0 0 14px;
  color: var(--smc-text);
  font-family: var(--smc-font-body);
  font-size: 16px;
  line-height: 1.75;
}
.smc-root .smc-copy:last-child { margin-bottom: 0; }
.smc-root .smc-answer {
  margin: 8px 0 18px;
  padding: 16px 18px;
  border-left: 4px solid var(--smc-accent);
  border-radius: 0 var(--smc-radius) var(--smc-radius) 0;
  background: color-mix(in srgb, var(--smc-accent) 6%, var(--smc-bg));
}
.smc-root .smc-answer .smc-copy { margin: 0; }
.smc-root .smc-figure { margin: 22px auto 26px; text-align: center; }
.smc-root .smc-image {
  display: block;
  width: 100%;
  max-width: 760px;
  height: auto;
  margin: 0 auto;
  border-radius: var(--smc-radius);
}
.smc-root .smc-caption {
  max-width: 760px;
  margin: 10px auto 0;
  color: var(--smc-muted);
  font-family: var(--smc-font-body);
  font-size: 14px;
  line-height: 1.5;
  text-align: center;
}
.smc-root .smc-list,
.smc-root .smc-steps { margin: 10px 0 18px; padding-left: 24px; }
.smc-root .smc-list-item { margin: 0 0 10px; padding-left: 4px; }
.smc-root .smc-list-item:last-child { margin-bottom: 0; }
.smc-root a {
  color: var(--smc-accent);
  font-family: var(--smc-font-body);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.smc-root a:focus-visible { outline: 2px solid var(--smc-primary); outline-offset: 3px; }
.smc-root .smc-subheading {
  margin: 0 0 10px;
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
  font-size: 19px;
  line-height: 1.35;
}
.smc-root .smc-mt-md { margin-top: 18px; }
.smc-root .smc-compare-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-top: 16px;
}
.smc-root .smc-compare-card {
  padding: 20px;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}
.smc-root .smc-card-highlight {
  border-color: color-mix(in srgb, var(--smc-primary) 35%, var(--smc-border));
  background: color-mix(in srgb, var(--smc-primary) 4%, var(--smc-surface));
}
.smc-root .smc-compare-card .smc-list { margin: 12px 0 0; padding-left: 18px; }
.smc-root .smc-step-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin: 16px 0;
}
.smc-root .smc-step-item {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  padding: 16px;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}
.smc-root .smc-step-badge {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--smc-primary);
  color: #fff;
  font-weight: 700;
  border-radius: 50%;
  font-size: 15px;
}
.smc-root .smc-step-body { font-size: 15px; line-height: 1.6; }
.smc-root .smc-notice {
  margin-top: 14px;
  padding: 14px 18px;
  background: color-mix(in srgb, var(--smc-accent) 6%, var(--smc-surface));
  border-left: 3px solid var(--smc-accent);
  border-radius: 0 var(--smc-radius) var(--smc-radius) 0;
}
.smc-root .smc-notice .smc-copy { margin: 0; font-size: 14px; }
.smc-root .smc-product {
  margin-top: 18px;
  padding: 20px 22px;
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  background: var(--smc-surface);
}
.smc-root .smc-product .smc-copy { margin: 0; }
.smc-root .smc-sources {
  margin-top: 18px;
  padding: 20px 22px;
  border: 1px solid var(--smc-border);
  border-bottom: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  background: var(--smc-surface);
  font-size: 15px;
}
.smc-root .smc-sources .smc-list { margin-bottom: 0; }
@container smc (max-width: 620px) {
  .smc-root { font-size: 15px; line-height: 1.7; }
  .smc-root > h2:first-child { font-size: 24px; }
  .smc-root > h2:first-child + p { padding: 15px 16px; }
  .smc-root .smc-section { padding: 20px 2px; }
  .smc-root .smc-heading { margin-bottom: 12px; font-size: 23px; }
  .smc-root .smc-copy { margin-bottom: 12px; font-size: 15px; }
  .smc-root .smc-answer { padding: 14px; }
  .smc-root .smc-figure { margin: 18px auto 22px; }
  .smc-root .smc-caption { font-size: 13px; }
  .smc-root .smc-list,
  .smc-root .smc-steps { padding-left: 21px; }
  .smc-root .smc-compare-grid,
  .smc-root .smc-step-grid {
    grid-template-columns: 1fr;
  }
  .smc-root .smc-product,
  .smc-root .smc-sources { padding: 16px; }
}

