.smc-brand-figure img {
  max-height: 620px;
  object-fit: contain;
}

.smc-brand-figure figcaption,
.smc-lifestyle figcaption {
  color: var(--smc-muted);
  font-size: 14px;
  line-height: 1.5;
}

.smc-compare-table {
  border-collapse: collapse;
  margin-top: 20px;
  width: 100%;
}

.smc-compare-table th,
.smc-compare-table td {
  border: 1px solid var(--smc-border);
  padding: 13px 14px;
  text-align: left;
  vertical-align: top;
}

.smc-compare-table th {
  background: color-mix(in srgb, var(--smc-primary) 10%, var(--smc-bg));
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
}

@container smc (max-width: 620px) {
  .smc-root {
    font-size: 16px;
  }

  .smc-root h2 {
    font-size: 24px;
    margin-top: 28px;
    padding-top: 22px;
  }

  .smc-root h3 {
    font-size: 19px;
  }

  .smc-summary,
  .smc-answer-box {
    padding: 16px;
  }

  .smc-compare-table,
  .smc-compare-table tbody,
  .smc-compare-table tr,
  .smc-compare-table th,
  .smc-compare-table td {
    display: block;
    width: 100%;
  }

  .smc-compare-table thead {
    display: none;
  }

  .smc-compare-table tr {
    border: 1px solid var(--smc-border);
    border-radius: var(--smc-radius);
    margin-top: 12px;
    overflow: hidden;
  }

  .smc-compare-table td {
    border: 0;
    border-top: 1px solid var(--smc-border);
  }

  .smc-compare-table td:first-child {
    background: color-mix(in srgb, var(--smc-primary) 10%, var(--smc-bg));
    border-top: 0;
    color: var(--smc-primary);
    font-weight: 700;
  }
}

.smc-root {
  color: var(--smc-text, #1e293b);
  font-family: var(--smc-font-body, system-ui, -apple-system, sans-serif);
  font-size: 16.5px;
  line-height: 1.8;
}

.smc-root h2,
.smc-root h3 {
  color: var(--smc-primary, #0f172a);
  font-family: var(--smc-font-heading, inherit);
  font-weight: 700;
  line-height: 1.35;
}

.smc-root h2 {
  font-size: clamp(22px, 3.5vw, 29px);
  margin: 38px 0 16px;
  padding-bottom: 10px;
  border-bottom: 2px solid color-mix(in srgb, var(--smc-primary, #0f172a) 15%, transparent);
}

.smc-root h3 {
  font-size: 18.5px;
  margin: 26px 0 10px;
}

.smc-root p {
  margin: 0 0 16px;
}

.smc-root a {
  color: var(--smc-accent, #c2410c);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.smc-root a:hover {
  color: var(--smc-primary, #0f172a);
}

.smc-root table {
  width: 100%;
  margin: 22px 0 32px;
  border-collapse: collapse;
  border-radius: var(--smc-radius, 8px);
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0,0,0,0.04);
}

.smc-root th,
.smc-root td {
  padding: 14px 16px;
  border: 1px solid var(--smc-border, #e2e8f0);
  text-align: left;
}

.smc-root th {
  background: var(--smc-primary, #0f172a);
  color: #ffffff;
  font-weight: 650;
  font-size: 15px;
}

.smc-root tbody tr:nth-child(even) {
  background: var(--smc-surface, #f8fafc);
}

.smc-root figure {
  margin: 26px 0 32px;
  text-align: center;
}

.smc-root figure img {
  max-width: 100%;
  height: auto;
  border-radius: var(--smc-radius, 8px);
  box-shadow: 0 4px 14px rgba(0,0,0,0.08);
}

.smc-root figure figcaption {
  font-size: 14px;
  color: #64748b;
  margin-top: 10px;
  font-style: italic;
}

.smc-cluster-box {
  margin: 36px 0;
  padding: 24px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-left: 4px solid var(--smc-accent, #c2410c);
  border-radius: var(--smc-radius, 8px);
}
